// ---------------------------------------------------------------------------
// Notification service. Notifications are generated by domain events in the
// donation/task services and read here.
// ---------------------------------------------------------------------------
import { IS_MOCK, http } from './apiClient';
import { getDb, mutate } from './db';
import { uid, nowISO, delay } from '../lib/utils';

/** Internal helper used by other services (mock mode only). */
export function pushNotification(db, userIds, { title, body, donationId = null }) {
  const list = Array.isArray(userIds) ? userIds : [userIds];
  for (const userId of list) {
    if (!userId) continue;
    db.notifications.unshift({
      id: uid('ntf'),
      userId,
      title,
      body,
      donationId,
      read: false,
      createdAt: nowISO(),
    });
  }
}

export async function getForUser(userId) {
  if (IS_MOCK) {
    await delay(120);
    return getDb()
      .notifications.filter((n) => n.userId === userId)
      .sort((a, b) => b.createdAt.localeCompare(a.createdAt));
  }
  const { data } = await http.get('/notifications');
  return data;
}

export async function markRead(notificationId) {
  if (IS_MOCK) {
    mutate((db) => {
      const n = db.notifications.find((x) => x.id === notificationId);
      if (n) n.read = true;
    });
    return;
  }
  await http.post(`/notifications/${notificationId}/read`);
}

export async function markAllRead(userId) {
  if (IS_MOCK) {
    mutate((db) => {
      db.notifications.forEach((n) => {
        if (n.userId === userId) n.read = true;
      });
    });
    return;
  }
  await http.post('/notifications/read-all');
}